      "keystrokes": "python3 -c "
import csv, json, glob

source_files = sorted(glob.glob('input_*.csv'))
all_rows = []
for fn in source_files:
    with open(fn, 'r') as f:
        for row in csv.DictReader(f):
            row['score'] = int(row['score'])
            all_rows.append(row)

team_counts = {}
for r in all_rows:
    team_counts[r['team']] = team_counts.get(r['team'], 0) + 1
team_sorted = sorted(team_counts.items(), key=lambda x: (-x[1], x[0]))

status_counts = {}
for r in all_rows:
    status_counts[r['status']] = status_counts.get(r['status'], 0) + 1
status_sorted = sorted(status_counts.items(), key=lambda x: x[0])

max_score = max(r['score'] for r in all_rows)
top_candidates = [r for r in all_rows if r['score'] == max_score]
top_row = min(top_candidates, key=lambda x: x['id'])

with open('summary.txt', 'w') as f:
    f.write('TEAM COUNTS\\n')
    for team, count in team_sorted:
        f.write(f'{team}: {count}\\n')
    f.write('\\n')
    f.write('STATUS COUNTS\\n')
    for status, count in status_sorted:
        f.write(f'{status}: {count}\\n')
    f.write('\\n')
    f.write('TOP SCORE\\n')
    f.write(f\"{top_row['id']}, {top_row['team']}, {top_row['score']}\\n\")

meta = {'source_files': source_files, 'row_count': len(all_rows), 'top_id': top_row['id'], 'top_team': top_row['team'], 'top_score': top_row['score']}
with open('summary_meta.json', 'w') as f:
    json.dump(meta, f, indent=2)
print('Done')
"
